// 1. Basic initialization and dereference (T must be readable)
std::istream_iterator<double> stream_it(std::cin);
std::istream_iterator<double> eos; // End-of-stream sentinel

// Read the first element
if (stream_it != eos) {
    double val = *stream_it;
    ++stream_it;
}


// 2. Populating a container directly (most common usage)
std::vector<int> numbers;
std::copy(std::istream_iterator<int>(std::cin),
          std::istream_iterator<int>(),
          std::back_inserter(numbers));


// 3. Range construction using a file stream
std::ifstream input_file("data.txt");
std::list<std::string> words(
    std::istream_iterator<std::string>(input_file),
    std::istream_iterator<std::string>()
);
